do $$ begin
if (select count(*) from batch_products b join public.categories c on c.handle=b.category and c.status='activa')<>9 then raise exception 'Missing active categories'; end if;
if exists(select 1 from batch_products b join public.products p using(handle) where not('catalog-gta-tumbler-20261105'=any(p.tags))) then raise exception 'Allocated product handle is not owned by this batch'; end if;
if exists(select 1 from batch_variants b join public.product_variants v using(sku) join public.products p on p.id=v.product_id where p.handle<>b.handle or v.color is distinct from b.color or v.size is distinct from b.size or v.option_label is distinct from b.option_label) then raise exception 'SKU collision'; end if;
end $$;
create temporary table inserted_products as
with added as (
insert into public.products(handle,title,description,category_id,base_price,images,tags,status,is_customizable,min_quantity,max_quantity)
select b.handle,b.title,b.description,c.id,b.base_price,b.images,b.tags,'oculto',false,1,b.max_quantity from batch_products b join public.categories c on c.handle=b.category
on conflict(handle) do nothing returning id,handle
) select * from added;
create temporary table inserted_variants as
with added as (
insert into public.product_variants(product_id,title,sku,price,stock,color,size,option_label,status)
select p.id,b.title,b.sku,b.price,b.stock,b.color,b.size,b.option_label,'disponible' from batch_variants b join public.products p using(handle)
where not exists(select 1 from public.product_variants v where v.product_id=p.id and v.color is not distinct from b.color and v.size is not distinct from b.size and v.option_label is not distinct from b.option_label)
on conflict(sku) do nothing returning id,product_id,sku,stock
) select * from added;
insert into public.inventory_movements(product_variant_id,movement_type,quantity,reason)
select id,'reposicion',stock,'Alta autorizada catalog-gta-tumbler-20261105: inventario inicial realmente insertado.' from inserted_variants;
do $$ begin
if (select count(*) from batch_products b join public.products p using(handle))<>9 then raise exception 'Expected 9 products'; end if;
if (select count(*) from batch_variants b join public.products p using(handle) join public.product_variants v on v.product_id=p.id and v.color is not distinct from b.color and v.size is not distinct from b.size and v.option_label is not distinct from b.option_label)<>237 then raise exception 'Expected 237 unique logical variants'; end if;
end $$;
select json_build_object('batch','catalog-gta-tumbler-20261105','inserted_products',(select json_agg(i) from inserted_products i),'inserted_variants',(select count(*) from inserted_variants),'inserted_stock',(select sum(stock) from inserted_variants),'products',(select json_agg(json_build_object('id',p.id,'handle',p.handle,'status',p.status)) from batch_products b join public.products p using(handle))) as receipt;
drop table inserted_variants,inserted_products,batch_variants,batch_products;
commit;
